const normalizeGlyph = ([glyphIndex, width, filePhrase, fileGlyph, flickerVariants]) => ({
  glyphIndex,
  width,
  height: GLYPH_HEIGHT,
  file: glyphAsset(filePhrase, fileGlyph),
  flickerVariants: flickerVariants.map(([phrase, glyph]) => glyphAsset(phrase, glyph)),
})

const normalizePhrase = ([id, text, glyphs]) => ({
  id,
  text,
  glyphs: glyphs.map(normalizeGlyph),
})

